CREATE TABLE `huespedes` (`id_huesped` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_huesped`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `categorias_habitacion` (`id_categoria_habitacion` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_categoria_habitacion`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `tipos_habitacion` (`id_tipo_habitacion` INT NOT NULL AUTO_INCREMENT, `id_categoria_habitacion` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `tarifa_noche` DECIMAL(11,2) NOT NULL, `disponibles` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_tipo_habitacion`), KEY `idx_recurso_categoria` (`id_categoria_habitacion`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_categoria_habitacion`) REFERENCES `categorias_habitacion` (`id_categoria_habitacion`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `hoteles` (`id_hotel` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_hotel`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `recepcionistas` (`id_recepcionista` INT NOT NULL AUTO_INCREMENT, `id_hotel` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_recepcionista`), KEY `idx_empleado_sede` (`id_hotel`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_hotel`) REFERENCES `hoteles` (`id_hotel`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `reservas` (`id_reserva` INT NOT NULL AUTO_INCREMENT, `id_huesped` INT NOT NULL, `id_recepcionista` INT NOT NULL, `id_hotel` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_reserva`), KEY `idx_operacion_persona` (`id_huesped`), KEY `idx_operacion_empleado` (`id_recepcionista`), KEY `idx_operacion_sede` (`id_hotel`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_huesped`) REFERENCES `huespedes` (`id_huesped`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_recepcionista`) REFERENCES `recepcionistas` (`id_recepcionista`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_hotel`) REFERENCES `hoteles` (`id_hotel`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `habitaciones_reservadas` (`id_habitacion_reservada` INT NOT NULL AUTO_INCREMENT, `id_reserva` INT NOT NULL, `id_tipo_habitacion` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_habitacion_reservada`), KEY `idx_detalle_operacion` (`id_reserva`), KEY `idx_detalle_recurso` (`id_tipo_habitacion`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_reserva`) REFERENCES `reservas` (`id_reserva`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_tipo_habitacion`) REFERENCES `tipos_habitacion` (`id_tipo_habitacion`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_reserva` (`id_pago_reserva` INT NOT NULL AUTO_INCREMENT, `id_reserva` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_reserva`), KEY `idx_pago_operacion` (`id_reserva`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_reserva`) REFERENCES `reservas` (`id_reserva`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `solicitudes_reserva` (`id_solicitud_reserva` INT NOT NULL AUTO_INCREMENT, `id_reserva` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_solicitud_reserva`), KEY `idx_evento_operacion` (`id_reserva`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_reserva`) REFERENCES `reservas` (`id_reserva`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
